/** Native Material navigation. All editing and settings use full pages, not action dialogs. */
public final class MainActivity extends AppCompatActivity {
    private final ExecutorService worker=Executors.newSingleThreadExecutor();
    public SharedPreferences prefs;public EditorPanel editorState;public LocationWeather locationWeather;
    private LinearLayout shell;private FrameLayout content;private MaterialToolbar toolbar;private Backdrop backdrop;
    private String tab="agenda";private boolean dayView,busy;private LocalDate selected=LocalDate.now();private Runnable backAction;private float downX,downY;
    public void onCreate(Bundle state){super.onCreate(state);prefs=getSharedPreferences("settings",0);if(!prefs.contains("device_id"))prefs.edit().putString("device_id",UUID.randomUUID().toString()).apply();locationWeather=new LocationWeather(this);
        FrameLayout base=new FrameLayout(this);backdrop=new Backdrop(this);base.addView(backdrop,new FrameLayout.LayoutParams(-1,-1));shell=Ui.column(this);base.addView(shell,new FrameLayout.LayoutParams(-1,-1));setContentView(base);
        ViewCompat.setOnApplyWindowInsetsListener(base,(v,insets)->{androidx.core.graphics.Insets bars=insets.getInsets(WindowInsetsCompat.Type.systemBars()|WindowInsetsCompat.Type.ime());shell.setPadding(0,bars.top,0,bars.bottom);return insets;});
        getOnBackPressedDispatcher().addCallback(this,new OnBackPressedCallback(true){public void handleOnBackPressed(){if(backAction!=null)backAction.run();else if(!"agenda".equals(tab)){tab="agenda";home();}else moveTaskToBack(true);}});
        backdrop.load();home();Updates.configureJob(this);
        if(state!=null){tab=state.getString("tab","agenda");dayView=state.getBoolean("day",false);selected=LocalDate.parse(state.getString("date",LocalDate.now().toString()));home();if(state.containsKey("editor"))try{edit(new JSONObject(state.getString("editor")));}catch(Exception ignored){}else if("外观与主题".equals(state.getString("screen")))new SettingsPanels(this).appearance();}else handleIntent(getIntent());
    }
    protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);handleIntent(i);}
    private void handleIntent(Intent i){try{if(i.hasExtra("record_id")){JSONObject r=Data.get(this).find(i.getStringExtra("record_id"));if(r!=null)detail(r);}else if(Intent.ACTION_SEND.equals(i.getAction())){JSONObject r=Data.make("inbox","通知 / 邮件").put("content",i.getStringExtra(Intent.EXTRA_TEXT));Data.get(this).save(r);changed();detail(r);}else if(i.getBooleanExtra("quick",false))edit(Data.make(i.getStringExtra("quick_kind")==null?"note":i.getStringExtra("quick_kind"),""));else if(i.getBooleanExtra("check_update",false))new SettingsPanels(this).updates();}catch(Exception e){message(e.getMessage());}}
    protected void onSaveInstanceState(Bundle state){state.putString("tab",tab);state.putString("date",selected.toString());state.putBoolean("day",dayView);state.putString("screen",toolbar.getTitle().toString());if(editorState!=null)state.putString("editor",editorState.draft().toString());super.onSaveInstanceState(state);}
    protected void onResume(){super.onResume();SyncJob.configure(this);if(editorState==null&&backAction==null&&"agenda".equals(tab))home();backdrop.active(true);ReminderReceiver.refresh(this);if(prefs.getBoolean("auto_location",false)&&checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED&&System.currentTimeMillis()-prefs.getLong("weather_updated",0)>6L*3600000)locationWeather.request();}
    protected void onPause(){backdrop.active(false);locationWeather.cancel();super.onPause();}
    protected void onDestroy(){worker.shutdown();backdrop.release();super.onDestroy();}
    public void message(String value){if(value!=null&&!isDestroyed())Snackbar.make(shell,value,Snackbar.LENGTH_LONG).show();}
    public interface Work{String run()throws Exception;}
    public void job(Work work,Runnable after){if(busy){message("正在处理，请稍候");return;}busy=true;LinearProgressIndicator progress=new LinearProgressIndicator(this);progress.setIndeterminate(true);shell.addView(progress,Math.min(1,shell.getChildCount()),new LinearLayout.LayoutParams(-1,Ui.dp(this,3)));worker.execute(()->{String result;try{result=work.run();}catch(Exception e){result=e.getMessage()==null?"操作失败":e.getMessage();}String value=result;runOnUiThread(()->{busy=false;if(isDestroyed())return;shell.removeView(progress);changed();if(after!=null&&editorState==null)after.run();message(value);});});}
    public void changed(){AgendaWidget.refresh(this);ReminderReceiver.refresh(this);}
    private void scaffold(String name,Runnable back,boolean navigation){shell.removeAllViews();backAction=back;toolbar=new MaterialToolbar(this);toolbar.setTitle(name);toolbar.setBackgroundColor(Ui.surface(this));if(back!=null){toolbar.setNavigationIcon(R.drawable.ic_back);toolbar.setNavigationContentDescription("返回");toolbar.setNavigationOnClickListener(v->back.run());}shell.addView(toolbar,new LinearLayout.LayoutParams(-1,Ui.dp(this,64)));content=new FrameLayout(this);shell.addView(content,new LinearLayout.LayoutParams(-1,0,1));
        if(navigation){BottomNavigationView nav=new BottomNavigationView(this);String[] labels={"今天","笔记","收集箱","课表","设置"},tabs={"agenda","note","inbox","course","settings"};int[] icons={R.drawable.ic_calendar,R.drawable.ic_note,R.drawable.ic_inbox,R.drawable.ic_course,R.drawable.ic_settings};for(int n=0;n<5;n++){nav.getMenu().add(0,100+n,n,labels[n]).setIcon(icons[n]);if(tab.equals(tabs[n]))nav.getMenu().getItem(n).setChecked(true);}nav.setLabelVisibilityMode(BottomNavigationView.LABEL_VISIBILITY_LABELED);nav.setOnItemSelectedListener(item->{tab=tabs[item.getItemId()-100];home();return true;});shell.addView(nav,new LinearLayout.LayoutParams(-1,-2));}
    }
    public LinearLayout fullPage(String title,Runnable back){scaffold(title,back,false);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);LinearLayout form=Ui.padded(this);scroll.addView(form);content.addView(scroll,new FrameLayout.LayoutParams(-1,-1));return form;}
    public void toolbarAction(String label,Runnable action){toolbar.getMenu().clear();toolbar.getMenu().add(label).setShowAsAction(MenuItem.SHOW_AS_ACTION_ALWAYS);toolbar.setOnMenuItemClickListener(item->{action.run();return true;});}
    public void home(){editorState=null;String name=tab.equals("agenda")?"今天":tab.equals("note")?"笔记":tab.equals("inbox")?"收集箱":tab.equals("course")?"课表":"设置";scaffold(name,null,true);try{if(tab.equals("agenda")||tab.equals("course"))schedule();else if(tab.equals("settings"))new SettingsPanels(this).root(homeForm());else recordList();}catch(Exception e){message("读取失败："+e.getMessage());}}
    private void schedule()throws Exception{
        LinearLayout page=homeForm();
        if(tab.equals("course")){
            page.addView(Ui.text(this,"课程就是每天的待办",23,true));page.addView(Ui.help(this,"当天课程自动出现在首页，支持提醒与完成。这里负责编辑和批量导入课表。"));
            page.addView(Ui.button(this,"编辑课表",true,()->ScheduleEditor.show(this,LocalDate.now(),true)));page.addView(Ui.button(this,"导入课表 CSV / ICS",false,()->pickFile(103,"*/*")));page.addView(Ui.button(this,"＋ 新建课程",false,()->newRecord("course")));toolbarAction("编辑",()->ScheduleEditor.show(this,LocalDate.now(),true));return;
        }
        page.addView(Ui.text(this,LocalDate.now().format(DateTimeFormatter.ofPattern("M月d日 EEEE",Locale.CHINA)),24,true));
        String weather=prefs.getString("weather_cache","");page.addView(Ui.button(this,weather.isEmpty()?"开启今天的位置天气":prefs.getString("city","")+"  "+weather,false,()->new SettingsPanels(this).weather()));
        DailyTasks.today(this,page);toolbarAction("编辑日程",()->ScheduleEditor.show(this,LocalDate.now(),false));
    }
    public void tasks(){taskBoard(0);}
    private void taskBoard(int mode){try{LinearLayout form=fullPage("待办事项",this::home);ChipGroup filter=new ChipGroup(this);filter.setSingleSelection(true);filter.setSelectionRequired(true);String[] names={"待完成","时间待定","已完成"};for(int n=0;n<3;n++){int index=n;Chip chip=new Chip(this);chip.setText(names[n]);chip.setCheckable(true);chip.setChecked(n==mode);chip.setOnClickListener(v->taskBoard(index));filter.addView(chip);}form.addView(filter);form.addView(Ui.button(this,"＋ 新建待办",true,()->newRecord("task")));JSONArray rows=Data.get(this).taskBoard(mode);for(int n=0;n<rows.length();n++){JSONObject r=rows.getJSONObject(n);MaterialCardView card=Ui.card(this);LinearLayout row=Ui.row(this);com.google.android.material.checkbox.MaterialCheckBox check=new com.google.android.material.checkbox.MaterialCheckBox(this);check.setChecked(!r.optString("completed").isEmpty());check.setContentDescription("完成或恢复「"+r.optString("title")+"」");check.setOnClickListener(v->{try{TaskActions.complete(this,r);changed();taskBoard(mode);}catch(Exception e){check.setChecked(!r.optString("completed").isEmpty());message(e.getMessage());}});row.addView(check);LinearLayout text=recordContents(r);row.addView(text,new LinearLayout.LayoutParams(0,-2,1));text.setOnClickListener(v->detail(r));card.addView(row);form.addView(card);}if(rows.length()==0)form.addView(Ui.help(this,"这里还没有事项。未确定日期的事情也可以先记下。"));}catch(Exception e){message(e.getMessage());}}
    public void newRecord(String kind){if(kind.equals("inbox")){captureText();return;}try{edit(Data.make(kind,""));}catch(Exception e){message(e.getMessage());}}
    private void captureText(){LinearLayout form=fullPage("粘贴通知",this::home);form.addView(Ui.help(this,"粘贴微信、QQ 或邮件正文。先放入收集箱，再确认日程或提取多个事项。"));TextInputEditText title=Ui.field(this,form,"标题","新通知",false),body=Ui.field(this,form,"通知正文","",true);body.setMinLines(8);Runnable save=()->{try{if(body.getText().toString().trim().isEmpty()){body.setError("请粘贴通知内容");return;}JSONObject r=Data.make("inbox",title.getText().toString().trim().isEmpty()?"新通知":title.getText().toString().trim()).put("content",body.getText().toString()).put("source","粘贴通知");Data.validate(r);Data.get(this).save(r);changed();detail(r);}catch(Exception e){message(e.getMessage());}};form.addView(Ui.button(this,"存入收集箱",true,save));toolbarAction("收集",save);}
    private void recordList()throws Exception{
        boolean notes=tab.equals("note");LinearLayout page=Ui.column(this);page.setPadding(Ui.dp(this,16),0,Ui.dp(this,16),0);content.addView(page);LinearLayout actions=Ui.row(this);actions.addView(Ui.button(this,notes?"＋ 文字笔记":"＋ 粘贴通知",true,()->newRecord(tab)),new LinearLayout.LayoutParams(0,-2,1));actions.addView(Ui.button(this,notes?"图片":"截图",false,()->pickFile(notes?105:106,"image/*")),new LinearLayout.LayoutParams(Ui.dp(this,90),-2));page.addView(actions);
        if(!notes)page.addView(Ui.help(this,"先收集，再确认。打开通知可提取多个事项，或直接确认成日程。"));
        final JSONArray[] rows={notes?Data.get(this).notes(""):Data.get(this).list(tab,200)};TextView status=Ui.help(this,notes?"支持 Markdown · 置顶笔记优先 · 文字与附图一起同步":"");
        TextInputEditText search=notes?Ui.field(this,page,"搜索笔记标题或正文","",false):null;page.addView(status);
        RecyclerView list=new RecyclerView(this);list.setLayoutManager(new LinearLayoutManager(this));RecyclerView.Adapter<RecordHolder> adapter=new RecyclerView.Adapter<RecordHolder>(){public RecordHolder onCreateViewHolder(ViewGroup p,int type){MaterialCardView card=Ui.card(MainActivity.this);RecyclerView.LayoutParams lp=new RecyclerView.LayoutParams(-1,-2);lp.setMargins(0,Ui.dp(MainActivity.this,5),0,Ui.dp(MainActivity.this,5));card.setLayoutParams(lp);return new RecordHolder(card);}public void onBindViewHolder(RecordHolder h,int position){try{JSONObject r=rows[0].getJSONObject(position);h.card.removeAllViews();LinearLayout body=recordContents(r);if(r.optBoolean("pinned"))body.addView(Ui.help(MainActivity.this,"已置顶"));h.card.addView(body);h.card.setOnClickListener(v->detail(r));}catch(Exception ignored){}}public int getItemCount(){return rows[0].length();}};list.setAdapter(adapter);page.addView(list,new LinearLayout.LayoutParams(-1,0,1));
        if(search!=null)search.addTextChangedListener(new android.text.TextWatcher(){final Handler handler=new Handler(Looper.getMainLooper());Runnable pending;public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence value,int start,int before,int count){if(pending!=null)handler.removeCallbacks(pending);String query=value.toString();pending=()->{if(isDestroyed()||!search.isAttachedToWindow())return;try{rows[0]=Data.get(MainActivity.this).notes(query);adapter.notifyDataSetChanged();status.setText(rows[0].length()==0?"没有找到笔记":"显示 "+rows[0].length()+" 条 · 置顶优先 · 正文与附图一起同步");}catch(Exception e){message(e.getMessage());}};handler.postDelayed(pending,200);}public void afterTextChanged(android.text.Editable value){}});
    }
    private static final class RecordHolder extends RecyclerView.ViewHolder{final MaterialCardView card;RecordHolder(MaterialCardView c){super(c);card=c;}}
    public LinearLayout recordContents(JSONObject r){LinearLayout l=Ui.padded(this);TextView title=Ui.text(this,r.optString("title"),16,true);title.setMaxLines(2);l.addView(title);String detail=r.optString("start_at").replace("T"," ");if(detail.isEmpty())detail=r.optString("time_hint");if(detail.isEmpty())detail=r.optString("source",r.optString("kind").equals("note")?"笔记":"时间待定");l.addView(Ui.help(this,detail));if(!r.optString("content").isEmpty()){TextView body=Ui.text(this,r.optString("content"),14,false);body.setMaxLines(3);body.setEllipsize(android.text.TextUtils.TruncateAt.END);l.addView(body);}if(!r.optString("image_base64").isEmpty())l.addView(Ui.help(this,"附有图片"));return l;}
    private void addRecord(LinearLayout parent,JSONObject r){MaterialCardView card=Ui.card(this);card.addView(recordContents(r));card.setOnClickListener(v->detail(r));parent.addView(card);}
    public void edit(JSONObject r){editorState=new EditorPanel(this,r);}
    public void detail(JSONObject r){editorState=null;LinearLayout form=fullPage(r.optString("kind").equals("inbox")?"待确认通知":"事项详情",this::home);form.addView(Ui.text(this,r.optString("title"),26,true));String date=r.optString("start_at");form.addView(Ui.help(this,date.isEmpty()?r.optString("time_hint","时间待定"):date.replace("T"," ")+(!r.optString("end_at").isEmpty()?" → "+r.optString("end_at").replace("T"," "):"")));if(!r.optString("location").isEmpty())form.addView(Ui.text(this,r.optString("location"),16,false));
        if(!r.optString("image_base64").isEmpty()){byte[] bytes=android.util.Base64.decode(r.optString("image_base64"),0);ImageView image=new ImageView(this);image.setAdjustViewBounds(true);image.setImageBitmap(BitmapFactory.decodeByteArray(bytes,0,bytes.length));form.addView(image,new LinearLayout.LayoutParams(-1,-2));}
        TextView body=Ui.text(this,r.optString("content"),16,false);if(r.optString("kind").equals("note"))NoteTools.render(body,r.optString("content"));body.setTextIsSelectable(true);body.setPadding(0,Ui.dp(this,16),0,Ui.dp(this,16));form.addView(body);form.addView(Ui.button(this,r.optString("kind").equals("inbox")?"确认并安排时间":"编辑事项",true,()->edit(r)));
        if(r.optString("kind").equals("inbox"))form.addView(Ui.button(this,"AI 提取多个事项",false,()->aiScreen(r)));else if(!r.optString("kind").equals("note"))form.addView(Ui.button(this,r.optString("completed").isEmpty()?"标记完成":"恢复为待办",false,()->{try{TaskActions.complete(this,r);changed();home();message("已更新");}catch(Exception e){message(e.getMessage());}}));else form.addView(Ui.button(this,"转为待办",false,()->{try{edit(new JSONObject(r.toString()).put("kind","task"));}catch(Exception e){message(e.getMessage());}}));
        if(r.optString("kind").equals("note"))form.addView(Ui.button(this,r.optBoolean("pinned")?"取消置顶":"置顶笔记",false,()->{try{JSONObject copy=new JSONObject(r.toString()).put("pinned",!r.optBoolean("pinned"));Data.get(this).save(copy);changed();detail(copy);}catch(Exception e){message(e.getMessage());}}));
        if(!date.isEmpty()){form.addView(Ui.button(this,"添加到系统日历",false,()->calendar(r)));form.addView(Ui.help(this,"系统时钟仅接收时分，请自行检查闹钟日期与重复设置。"));form.addView(Ui.button(this,"打开系统时钟设置闹钟",false,()->alarm(r)));}form.addView(Ui.button(this,"添加后续阶段任务",false,()->followup(r)));form.addView(Ui.button(this,"删除事项",false,()->{try{JSONObject deleted=new JSONObject(r.toString()).put("deleted",true);Data.get(this).save(deleted);changed();home();Snackbar.make(shell,"已删除",Snackbar.LENGTH_LONG).setAction("撤销",v->{try{deleted.put("deleted",false);Data.get(this).save(deleted);changed();home();}catch(Exception e){message(e.getMessage());}}).show();}catch(Exception e){message(e.getMessage());}}));
    }
    private void followup(JSONObject r){LinearLayout form=fullPage("添加后续任务",()->detail(r));form.addView(Ui.help(this,"实际完成「"+r.optString("title")+"」后，再开始下一阶段。"));TextInputEditText title=Ui.field(this,form,"标题","",false),days=Ui.field(this,form,"延迟天数（0为当天）","0",false);days.setInputType(2);form.addView(Ui.button(this,"添加后续任务",true,()->{try{int offset=Integer.parseInt(days.getText().toString());if(title.getText().toString().trim().isEmpty()||offset<0||offset>3650)throw new Exception("请填写标题，天数需为0–3650");if(!r.optString("completed").isEmpty())throw new Exception("请为尚未完成的事项添加后续任务");Data.get(this).save(Data.make("task",title.getText().toString().trim()).put("trigger_after",r.getString("id")).put("offset_days",offset).put("activation","waiting").put("time_hint","完成「"+r.optString("title")+"」后 "+offset+" 天"));changed();tasks();}catch(Exception e){message(e.getMessage());}}));}
    private void aiScreen(JSONObject r){LinearLayout form=fullPage("提取日程",()->detail(r));form.addView(Ui.text(this,"把通知变成明确的安排",23,true));form.addView(Ui.help(this,"标题、正文和附图将发送到你配置的 AI 服务。结果会先进入收集箱，由你确认。\n"+prefs.getString("api_url","尚未配置接口")));form.addView(Ui.button(this,"开始提取",true,()->job(()->{JSONArray rows=PlannerServices.extract(this,r);for(int i=0;i<rows.length();i++)Data.get(this).save(rows.getJSONObject(i));return "已提取 "+rows.length()+" 项，请逐项确认";},()->{tab="inbox";home();})));form.addView(Ui.text(this,r.optString("content"),15,false));}
    private void calendar(JSONObject r){try{long start=LocalDateTime.parse(r.getString("start_at")).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli(),end=r.optString("end_at").isEmpty()?start+3600000:LocalDateTime.parse(r.getString("end_at")).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();startActivity(new Intent(Intent.ACTION_INSERT,CalendarContract.Events.CONTENT_URI).putExtra(CalendarContract.Events.TITLE,r.optString("title")).putExtra(CalendarContract.EXTRA_EVENT_BEGIN_TIME,start).putExtra(CalendarContract.EXTRA_EVENT_END_TIME,end).putExtra(CalendarContract.Events.EVENT_LOCATION,r.optString("location")).putExtra(CalendarContract.Events.DESCRIPTION,r.optString("content")));}catch(Exception e){message("未能打开系统日历："+e.getMessage());}}
    private void alarm(JSONObject r){try{LocalDateTime date=LocalDateTime.parse(r.getString("start_at"));startActivity(new Intent(AlarmClock.ACTION_SET_ALARM).putExtra(AlarmClock.EXTRA_HOUR,date.getHour()).putExtra(AlarmClock.EXTRA_MINUTES,date.getMinute()).putExtra(AlarmClock.EXTRA_MESSAGE,r.optString("title")).putExtra(AlarmClock.EXTRA_SKIP_UI,false));}catch(Exception e){message("未找到兼容的系统时钟");}}
    public void notificationPermission(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},200);}
    public LinearLayout homeForm(){ScrollView scroll=new ScrollView(this);LinearLayout form=Ui.padded(this);scroll.addView(form);content.addView(scroll);return form;}
    public void checkUpdates(){if(busy)return;busy=true;worker.execute(()->{try{JSONObject info=Updates.check(this);runOnUiThread(()->{busy=false;if(isDestroyed())return;if(info==null)message("当前已是最新版本");else new SettingsPanels(this).showUpdate(info);});}catch(Exception e){runOnUiThread(()->{busy=false;message(e.getMessage());});}});}
    public void pickFile(int code,String mime){startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(mime),code);}
    public void refreshBackdrop(){backdrop.load();}
    public void refreshWeatherUi(){if(editorState!=null)return;if("位置与天气".equals(toolbar.getTitle().toString()))new SettingsPanels(this).weather();else if(backAction==null&&"agenda".equals(tab))home();}
    public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==201){if(results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED)locationWeather.request();else{prefs.edit().putBoolean("auto_location",false).apply();message("未授权位置，可继续使用手动位置与离线功能");}}else if(request==200&&results.length>0&&results[0]!=PackageManager.PERMISSION_GRANTED)message("通知权限未开启，事项仍已保存");}
    protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();
        if(code==101)job(()->{try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){out.write(Data.get(this).exportFile().toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}return "已导出同步文件";},null);
        else if(code==102)job(()->{try(InputStream in=getContentResolver().openInputStream(uri)){return Data.get(this).importFile(new JSONObject(Network.read(in,16*1024*1024)));}},this::home);
        else if(code==103){if(busy)return;busy=true;worker.execute(()->{try{JSONArray items;try(InputStream in=getContentResolver().openInputStream(uri)){items=Imports.timetable(Network.read(in,4*1024*1024));}runOnUiThread(()->{busy=false;if(!isDestroyed())importPreview(items);});}catch(Exception e){runOnUiThread(()->{busy=false;message(e.getMessage());});}});}
        else if(code==104||code==105||code==106)job(()->saveImage(uri,code),this::home);
    }
    private String saveImage(Uri uri,int code)throws Exception{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(in,null,bounds);}if(bounds.outWidth<=0)throw new Exception("无法读取图片");BitmapFactory.Options opts=new BitmapFactory.Options();opts.inSampleSize=1;while(Math.max(bounds.outWidth,bounds.outHeight)/opts.inSampleSize>1400)opts.inSampleSize*=2;Bitmap bitmap;try(InputStream in=getContentResolver().openInputStream(uri)){bitmap=BitmapFactory.decodeStream(in,null,opts);}if(bitmap==null)throw new Exception("无法读取图片");if(code==104){try(OutputStream out=openFileOutput("wallpaper.jpg",0)){bitmap.compress(Bitmap.CompressFormat.JPEG,85,out);}finally{bitmap.recycle();}runOnUiThread(this::refreshBackdrop);return "壁纸已更新";}
        ByteArrayOutputStream image=new ByteArrayOutputStream();try{bitmap.compress(Bitmap.CompressFormat.JPEG,75,image);while(image.size()>36000){Bitmap next=Bitmap.createScaledBitmap(bitmap,Math.max(1,bitmap.getWidth()*3/4),Math.max(1,bitmap.getHeight()*3/4),true);bitmap.recycle();bitmap=next;image.reset();bitmap.compress(Bitmap.CompressFormat.JPEG,70,image);}}finally{bitmap.recycle();}JSONObject record=Data.make(code==105?"note":"inbox",code==105?"图片笔记":"截图 · 待识别").put("image_base64",android.util.Base64.encodeToString(image.toByteArray(),2));Data.validate(record);Data.get(this).save(record);return "已保存压缩图片";
    }
    private void importPreview(JSONArray items){LinearLayout form=fullPage("导入预览 · "+items.length()+" 条",this::home);form.addView(Ui.help(this,"检查课程、日期、单双周与教室。已有事项不会重复导入。"));form.addView(Ui.button(this,"确认导入",true,()->job(()->{int count=0;for(int i=0;i<items.length();i++){JSONObject r=items.getJSONObject(i);if(Data.get(this).find(r.getString("id"))==null){Data.get(this).save(r);count++;}}return "已导入 "+count+" 条";},this::home)));for(int i=0;i<Math.min(20,items.length());i++)try{form.addView(recordContents(items.getJSONObject(i)));}catch(Exception ignored){}if(items.length()>20)form.addView(Ui.help(this,"另有 "+(items.length()-20)+" 条，导入后可在周课表查看。"));}
    public boolean dispatchTouchEvent(MotionEvent e){if(e.getAction()==MotionEvent.ACTION_DOWN){downX=e.getX();downY=e.getY();}if(e.getAction()==MotionEvent.ACTION_UP&&editorState==null&&prefs!=null&&prefs.getBoolean("swipe",true)&&downX<Ui.dp(this,28)&&downY>getResources().getDisplayMetrics().heightPixels*.7f&&e.getX()-downX>Ui.dp(this,110)&&Math.abs(e.getY()-downY)<Ui.dp(this,50)){newRecord("note");return true;}return super.dispatchTouchEvent(e);}
}
